// SHADOW MAPPING CODE

#define SHADOW_SIZE 1024
GLuint shadowMapFbo;      // shadow map framebuffer object
GLuint shadowMapTexture;  // shadow map texture
GLuint shadowMapShader;   // shadow map shader
GLuint pointLightShadowMapFbo;
GLuint pointLightShadowMapTexture;
GLuint pointLightShadowMapShader;

bool setupShadowMap()
{
    // create the FBO for rendering shadows
    glGenFramebuffers(1, &shadowMapFbo);
    glBindFramebuffer(GL_FRAMEBUFFER, shadowMapFbo);

    // attach a texture object to the framebuffer
    glGenTextures(1, &shadowMapTexture);
    glBindTexture(GL_TEXTURE_2D, shadowMapTexture);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_DEPTH_COMPONENT, SHADOW_SIZE, SHADOW_SIZE,
                 0, GL_DEPTH_COMPONENT, GL_FLOAT, NULL);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT, GL_TEXTURE_2D, shadowMapTexture, 0);

    // check if we did everything right
    if (glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE)
    {
        std::cout << "Could not create custom framebuffer.\n";
        return false;
    }

    // load the shader program for drawing the shadow map
    shadowMapShader = gdevLoadShader("gdev32s.vs", "gdev32s.fs");
    if (! shadowMapShader)
        return false;

    // set the framebuffer back to the default onscreen buffer
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    return true;
}

bool setupPointLightShadowMap()
{
    // create the FBO for rendering shadows
    glGenFramebuffers(1, &pointLightShadowMapFbo);
    glBindFramebuffer(GL_FRAMEBUFFER, pointLightShadowMapFbo);

    // attach a texture object to the framebuffer
    glGenTextures(1, &pointLightShadowMapTexture);
    glBindTexture(GL_TEXTURE_2D, pointLightShadowMapTexture);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_DEPTH_COMPONENT, SHADOW_SIZE, SHADOW_SIZE,
                 0, GL_DEPTH_COMPONENT, GL_FLOAT, NULL);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT, GL_TEXTURE_2D, pointLightShadowMapTexture, 0);

    // check if we did everything right
    if (glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE)
    {
        std::cout << "Could not create custom framebuffer.\n";
        return false;
    }

    // load the shader program for drawing the shadow map
    pointLightShadowMapShader = gdevLoadShader("gdev32s.vs", "gdev32s.fs");
    if (! pointLightShadowMapShader)
        return false;

    // set the framebuffer back to the default onscreen buffer
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
    return true;
}

glm::mat4 renderShadowMap()
{
    // use the shadow framebuffer for drawing the shadow map
    glBindFramebuffer(GL_FRAMEBUFFER, shadowMapFbo);

    // the viewport should be the size of the shadow map
    glViewport(0, 0, SHADOW_SIZE, SHADOW_SIZE);

    // clear the shadow map
    // (we don't have a color buffer attachment, so no need to clear that)
    glClear(GL_DEPTH_BUFFER_BIT);

    // using the shadow map shader...
    glUseProgram(shadowMapShader);

    // ... set up the light space matrix...
    // (note that if you use a spot light, the FOV and the center position
    // vector should be set to the spot light's outer cone angle times 2
    // and the spot light's focus point, respectively)
    glm::mat4 lightTransform;
    lightTransform = glm::perspective(glm::cos(glm::radians(outerCutOffValue)),       // fov
                                      1.0f,                      // aspect ratio
                                      1.0f,                      // near plane
                                      10.0f);                   // far plane
    lightTransform *= glm::lookAt(spotLightPosition,                 // eye position
                                  spotLightPosition + lightDirection,   // center position 
                                  glm::vec3(0.0f, 1.0f, 0.0f));  // up vector
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "lightTransform"),
                       1, GL_FALSE, glm::value_ptr(lightTransform));

    // ... set up the model matrix... (just identity for this demo)
    // have model matrix for normals
    glm::mat4 modelMatrix = glm::mat4(1.0f);

// for main platform
    glm::mat4 matrix1;
    matrix1 = glm::translate(modelMatrix, glm::vec3(-1.0f, 0.2f, 0.0f));
    matrix1 = glm::scale(matrix1, glm::vec3(4.0f, 1.0f, 2.0f));
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrix1));

    // ... then draw our triangles
    glBindVertexArray(vao1);
    glDrawArrays(GL_TRIANGLES, 0, sizeof(mainVertices) / (11 * sizeof(float)));

// for smaller platforms
    // first platform
    glm::mat4 matrix2;
    matrix2 = glm::translate(modelMatrix, glm::vec3(-0.5f, 1.5f, -0.2f));
    matrix2 = glm::scale(matrix2, glm::vec3(2.0f, 1.0f, 1.5f));
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrix2));
    
    // ... then draw our triangles
    glBindVertexArray(vao2);
    glDrawArrays(GL_TRIANGLES, 0, sizeof(Vertices) / (11 * sizeof(float)));

    // second platform
    glm::mat4 matrix3;
    matrix3 = glm::translate(modelMatrix, glm::vec3(-2.5f, 1.5f, -0.2f));
    matrix3 = glm::scale(matrix3, glm::vec3(2.0f, 1.0f, 1.5f));
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrix3));

    // ... then draw our triangles
    glBindVertexArray(vao3);
    glDrawArrays(GL_TRIANGLES, 0, sizeof(Vertices) / (11 * sizeof(float)));

    // third platform
    glm::mat4 matrix4;
    matrix4 = glm::translate(modelMatrix, glm::vec3(-3.5f, 0.9f, -0.2f));
    matrix4 = glm::scale(matrix4, glm::vec3(2.0f, 1.0f, 1.5f));
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrix4));

    // ... then draw our triangles
    glBindVertexArray(vao4);
    glDrawArrays(GL_TRIANGLES, 0, sizeof(Vertices) / (11 * sizeof(float)));

    // fourth platform
    glm::mat4 matrix5;
    matrix5 = glm::translate(modelMatrix, glm::vec3(0.5f, 0.9f, -0.2f));
    matrix5 = glm::scale(matrix5, glm::vec3(2.0f, 1.0f, 1.5f));
    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrix5));

    // ... then draw our triangles
    glBindVertexArray(vao5);
    glDrawArrays(GL_TRIANGLES, 0, sizeof(Vertices) / (11 * sizeof(float)));
    
    // setting up kirby
    // ... timing settings
    const float pi = 3.14159265358979323846f;
    float timer = sin(glfwGetTime() / 2 - pi);
    
    if (timer < 0){
        jump = fabs(sin(glfwGetTime() * 4)) / 4;
        arc = (sin(glfwGetTime() - pi/2) + 1.0f) / 1.5f;
        if (onRight){
            distance = (sin(glfwGetTime() / 2 - pi/2) + 1.0f) * 2.0f;
        }
        else {
            distance = (sin(glfwGetTime() / 2 + pi/2) + 1.0f) * 2.0f;
        }

        switchCheck = true;
    }
    else {
        walk = (sin(glfwGetTime() * 4)) / 3.0f;

        if (switchCheck){
            if (onRight) {
                onRight = false;
            }
            else {
                onRight = true;
            }
            
            switchCheck = false;
        }
    }

// ... calculate matrix for kirby ...
    glm::mat4 matrixKirby;
    matrixKirby = glm::translate(modelMatrix, glm::vec3(-3.0f + distance + walk, 1.08f + jump + arc, -0.75f));

    if (timer >= 0){
        matrixKirby = glm::rotate(matrixKirby, glm::radians(walk * 180.0f - 90.0f), glm::vec3(0.0f, 1.0f, 0.0f));
        matrixKirby = glm::scale(matrixKirby, glm::vec3(1.0f, 1.0f, 1.0f));
    }
    else {
        if (onRight){
            matrixKirby = glm::rotate(matrixKirby, glm::radians(-45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
        }
        else {
            matrixKirby = glm::rotate(matrixKirby, glm::radians(-135.0f), glm::vec3(0.0f, 1.0f, 0.0f));
        }

        matrixKirby = glm::scale(matrixKirby, glm::vec3(1.0f + jump, 1.0f + jump, 1.0f + jump));
    }

    matrixKirby = glm::scale(matrixKirby, glm::vec3(0.05f, 0.05f, 0.05f));


    glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
    1, GL_FALSE, glm::value_ptr(matrixKirby));

    // ... then draw our triangles
    if (timer >= 0){
        glBindVertexArray(vaoKirby);
        glDrawArrays(GL_TRIANGLES, 0, sizeof(kirbyVertices) / (11 * sizeof(float)));
    }
    else {
        glBindVertexArray(vaoKirbyFly);
        glDrawArrays(GL_TRIANGLES, 0, sizeof(kirbyFlyVertices) / (11 * sizeof(float)));
    }

// // for Warp Star
//     // warp star
//     glm::mat4 matrixWarpStar;
//     matrixWarpStar = glm::translate(modelMatrix, glm::vec3(-1.0f, 0.75f, -0.5f));
//     matrixWarpStar = glm::rotate(matrixWarpStar, glm::radians(90.0f), glm::vec3(0.0f, 0.0f, 1.0f));
//     matrixWarpStar = glm::scale(matrixWarpStar, glm::vec3(0.07f, 0.07f, 0.07f));
//     glUniformMatrix4fv(glGetUniformLocation(shadowMapShader, "matrix"),
//     1, GL_FALSE, glm::value_ptr(matrixWarpStar));
    
//     // ... then draw our triangles
//     glBindVertexArray(vaoWarpStar);
//     glDrawArrays(GL_TRIANGLES, 0, sizeof(warpStarVertices) / (11 * sizeof(float)));

    // set the framebuffer back to the default onscreen buffer
    glBindFramebuffer(GL_FRAMEBUFFER, 0);

    // before drawing the final scene, we need to set drawing to the whole window
    int width, height;
    glfwGetFramebufferSize(pWindow, &width, &height);
    glViewport(0, 0, width, height);

    // we will need the light transformation matrix again in the main rendering code
    return lightTransform;
}

